// ============================================================================
// Netflix-style Detail View - Cinematic Streaming Design
// ============================================================================

:host {
    --poster-width: 220px;
    --poster-shadow: 0 8px 40px rgba(0, 0, 0, 0.15);
    --content-max-width: 1400px;

    // Light theme colors (default - no .dark-theme class on body)
    --hero-gradient-start: rgba(255, 250, 245, 0);
    --hero-gradient-mid: rgba(255, 250, 245, 0.75);
    --hero-gradient-end: rgba(255, 250, 245, 1);
    --surface-bg: #fffaf5;
    --text-primary: #1a1a1a;
    --text-secondary: rgba(26, 26, 26, 0.75);
    --text-muted: rgba(26, 26, 26, 0.5);
    --accent-color: #b81d24;
    --tag-bg: rgba(0, 0, 0, 0.06);
    --tag-border: rgba(0, 0, 0, 0.12);

    width: 100%;
    height: 100%;
    display: block;
    overflow: hidden;
    background: var(--surface-bg);
    color: var(--text-primary);
}

// Dark theme overrides - cinematic dark mode
:host-context(.dark-theme) {
    --hero-gradient-start: rgba(20, 20, 20, 0);
    --hero-gradient-mid: rgba(20, 20, 20, 0.7);
    --hero-gradient-end: rgba(20, 20, 20, 1);
    --surface-bg: #141414;
    --text-primary: #fff;
    --text-secondary: rgba(255, 255, 255, 0.7);
    --text-muted: rgba(255, 255, 255, 0.5);
    --accent-color: #e50914;
    --tag-bg: rgba(255, 255, 255, 0.1);
    --tag-border: rgba(255, 255, 255, 0.2);
    --poster-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}

// ============================================================================
// Hero Section - Full container with backdrop
// ============================================================================

.hero {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: var(
        --surface-bg
    ); // Solid background prevents any bleed-through

    // Floating back button over backdrop
    &__back-button {
        position: absolute;
        top: 16px;
        left: 16px;
        z-index: 10;
        display: flex;
        align-items: center;
        justify-content: center;
        width: 40px;
        height: 40px;
        border-radius: 50%;
        background: rgba(0, 0, 0, 0.5);
        backdrop-filter: blur(8px);
        border: none;
        cursor: pointer;
        transition: all 0.2s ease;
        color: #fff;

        &:hover {
            background: rgba(0, 0, 0, 0.7);
            transform: scale(1.05);
        }

        mat-icon {
            font-size: 24px;
            width: 24px;
            height: 24px;
        }
    }

    // Backdrop image layer - fixed at top, never repeats
    &__backdrop {
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: auto; // Only use height, not bottom
        height: 60%;
        background-size: cover;
        background-position: center 20%;
        background-repeat: no-repeat;
        z-index: 0;
        overflow: hidden;

        // Fallback blur effect when using poster as backdrop
        &--blurred {
            filter: blur(40px) saturate(1.3);
            transform: scale(1.4);
            height: 65%;
        }
    }

    // Gradient overlays for text legibility
    &__vignette {
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0; // Full height to cover everything
        z-index: 1;
        pointer-events: none;
        background: linear-gradient(
            to bottom,
            transparent 0%,
            transparent 35%,
            var(--surface-bg) 55%,
            var(--surface-bg) 100%
        );

        // Top area gradient for text legibility over backdrop
        &::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 60%;
            background: linear-gradient(
                to top,
                var(--hero-gradient-end) 0%,
                var(--hero-gradient-mid) 50%,
                var(--hero-gradient-start) 100%
            );
        }

        // Side fade for poster area
        &::after {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            height: 50%;
            width: 40%;
            background: linear-gradient(
                to right,
                var(--hero-gradient-mid) 0%,
                var(--hero-gradient-start) 100%
            );
        }
    }

    // Scrollable content area
    &__content {
        position: absolute;
        inset: 0;
        z-index: 2;
        display: flex;
        gap: 32px;
        align-items: flex-start;
        padding: 140px 40px 60px;
        max-width: var(--content-max-width);
        margin: 0 auto;
        overflow-y: auto;
        overflow-x: hidden;
        box-sizing: border-box;

        // Hide scrollbar but keep functionality
        scrollbar-width: none;
        -ms-overflow-style: none;
        &::-webkit-scrollbar {
            display: none;
        }
    }

    // Error state
    &__error {
        flex-direction: column;
        align-items: center;
        justify-content: center;
        text-align: center;
        gap: 16px;

        .error-icon {
            font-size: 64px;
            width: 64px;
            height: 64px;
            color: var(--text-muted);
        }

        .error-title {
            font-size: 1.25rem;
            font-weight: 500;
            color: var(--text-secondary);
            margin: 0;
        }
    }
}

// ============================================================================
// Poster Card - Floating with shadow
// ============================================================================

.poster {
    flex-shrink: 0;
    width: var(--poster-width);
    align-self: flex-start;

    &:hover .poster__image {
        transform: scale(1.02);
    }

    &__image {
        width: 100%;
        aspect-ratio: 2 / 3;
        object-fit: cover;
        border-radius: 8px;
        box-shadow: var(--poster-shadow);
        background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
        transition: transform 0.3s ease;
    }

    &__placeholder {
        width: 100%;
        aspect-ratio: 2 / 3;
        border-radius: 8px;
        background: linear-gradient(135deg, #3a3a3a 0%, #2a2a2a 100%);
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        color: rgba(255, 255, 255, 0.8);
        box-shadow: var(--poster-shadow);
        overflow: hidden;

        &-icon {
            font-size: 48px;
            width: 48px;
            height: 48px;
            opacity: 0.5;
            margin-bottom: 12px;
        }

        &-text {
            font-size: 1rem;
            font-weight: 500;
            text-align: center;
            display: -webkit-box;
            -webkit-line-clamp: 4;
            -webkit-box-orient: vertical;
            overflow: hidden;
            overflow-wrap: anywhere;
            padding: 16px;
        }
    }
}

// ============================================================================
// Details Section - Title, metadata, description
// ============================================================================

.details {
    flex: 1;
    min-width: 0;
    padding-bottom: 24px;

    &__title {
        font-size: clamp(1.75rem, 4vw, 3rem);
        font-weight: 700;
        line-height: 1.1;
        margin: 0 0 16px 0;
        letter-spacing: -0.02em;
        text-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
        overflow-wrap: anywhere;
        display: -webkit-box;
        -webkit-line-clamp: 3;
        -webkit-box-orient: vertical;
        overflow: hidden;
