        ::ng-deep .loader {
            background-color: rgba(255, 255, 255, 0.1);
        }
    }
}

.poster {
    // ... existing styles ...
    // Ensure poster container has height/ratio for skeleton
    min-height: 330px; // Fallback
    aspect-ratio: 2 / 3;
}

